e\": \"0.180.0\",\n    \"zustand\": \"^5.0.12\"\n  },\n  \"devDependencies\": {\n    \"@eslint/js\": \"^10.0.1\",\n    \"@types/react\": \"^18.3.3\",\n    \"@types/react-dom\": \"^18.3.0\",\n    \"@types/react-test-renderer\": \"18.3.0\",\n    \"@types/semver\": \"7.8.0\",\n    \"@typescript-eslint/eslint-plugin\": \"^8.59.3\",\n    \"@typescript-eslint/parser\": \"^8.59.3\",\n    \"@vitejs/plugin-react\": \"^4.3.1\",\n    \"autoprefixer\": \"^10.4.19\",\n    \"eslint\": \"^10.13.0\",\n    \"eslint-plugin-react-hooks\": \"^7.1.1\",\n    \"eslint-plugin-react-refresh\": \"^0.4.26\",\n    \"globals\": \"^17.13.0\",\n    \"lucide-react\": \"^1.14.0\",\n    \"patch-package\": \"^8.0.1\",\n    \"postcss\": \"^8.4.38\",\n    \"prettier\": \"^3.2.5\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\",\n    \"react-test-renderer\": \"18.3.1\",\n    \"tailwindcss\": \"^3.4.19\",\n    \"typescript\": \"^5.5.3\",\n    \"vite\": \"^5.3.1\",\n    \"vitest\": \"^4.0.18\"\n  },\n  \"allowScripts\": {\n    \"esbuild@0.21.5\": true,\n    \"esbuild@0.28.2\": true\n  }\n}\n"
